const pipeline = $('Take 1 Row').item.json;
const blogs = $input.all().map(i => i.json);
const blog = blogs.find(b => String(b.ID_BLOG).trim() === String(pipeline.ID_BLOG).trim()) || {};

const idioma = blog.IDIOMA || pipeline.IDIOMA || 'es';
const nicho   = blog.NICHO   || pipeline.NICHO   || 'general';
const bloggerId = String(blog.BLOGGER_ID || '').trim();

if (!bloggerId) {
  throw new Error('BLOGGER_ID vacío para ID_BLOG=' + pipeline.ID_BLOG + '. Verifica BLOGS_SITES_CONFIG.');
}

const enEs = idioma !== 'en';
const sysPrompt = enEs
  ? 'Eres experto SEO. Escribe artículos en español usando HTML puro. Sin markdown, sin bloques de código.'
  : 'You are an SEO expert. Write articles in English using pure HTML only. No markdown, no code blocks.';

const userPrompt = enEs
  ? `Escribe un artículo SEO completo sobre: "${pipeline.TEMA_ARTICULO}"\nPalabras clave: ${pipeline.KEYWORD || pipeline.TEMA_ARTICULO}\nNicho: ${nicho}\nMínimo 1200 palabras. Devuelve SOLO HTML puro empezando con <h1>. Sin texto previo ni explicaciones.`
  : `Write a complete SEO article about: "${pipeline.TEMA_ARTICULO}"\nKeywords: ${pipeline.KEYWORD || pipeline.TEMA_ARTICULO}\nNiche: ${nicho}\nMinimum 1200 words. Return ONLY pure HTML starting with <h1>. No preamble or explanations.`;

console.log('Pipeline row:', pipeline.ID_UNICO, '| Blog:', bloggerId, '| row_number:', pipeline.row_number);

return [{ json: {
  ID_UNICO:      pipeline.ID_UNICO,
  TEMA_ARTICULO: pipeline.TEMA_ARTICULO,
  ID_BLOG:       pipeline.ID_BLOG,
  BLOGGER_ID:    bloggerId,
  NICHO:         nicho,
  IDIOMA:        idioma,
  KEYWORD:       pipeline.KEYWORD || '',
  row_number:    pipeline.row_number,
  systemPrompt:  sysPrompt,
  userPrompt:    userPrompt
} }];

const prev = $('Preparar Datos').item.json;
const res  = $json;

if (!res.choices || !res.choices[0]) {
  throw new Error('DeepSeek sin respuesta válida: ' + JSON.stringify(res).slice(0, 300));
}

let html = (res.choices[0].message.content || '').trim();
html = html.replace(/^```html\s*/i,'').replace(/^```\s*/i,'').replace(/\s*```\s*$/i,'').trim();

if (!html || html.length < 100) {
  throw new Error('HTML vacío o demasiado corto: ' + html.slice(0, 100));
}

console.log('HTML generado: ' + html.length + ' chars | tokens: ' + (res.usage?.total_tokens || 0));

return [{ json: {
  ...prev,
  HTML_FINAL: html,
  TOKENS:     res.usage?.total_tokens || 0
} }];

const bloggerResp = $json;
const prev = $('Extraer HTML').item.json;

if (!bloggerResp.id) {
  throw new Error('Blogger no devolvió post ID: ' + JSON.stringify(bloggerResp).slice(0, 300));
}

const postUrl = bloggerResp.url || bloggerResp.selfLink || '';
const row     = prev.row_number;

console.log('Post publicado: ' + postUrl + ' | row=' + row);

return [{ json: {
  ID_UNICO:   prev.ID_UNICO,
  post_url:   postUrl,
  post_id:    String(bloggerResp.id),
  row_number: row,
  updateBody: {
    valueInputOption: 'USER_ENTERED',
    data: [
      { range: 'CONTENT_PIPELINE!B' + row, values: [['PUBLISHED']] },
      { range: 'CONTENT_PIPELINE!K' + row, values: [[postUrl]] }
    ]
  }
} }];
